2| <!doctype html>
3| <html lang="en">
4| <head>
5| <meta charset="utf-8">
6| <meta name="viewport" content="width=device-width, initial-scale=1">
7| <title>Comet Lane Runner</title>
8| <style>
9|   html, body {
10|     margin: 0; padding: 0; width: 100%; height: 100%;
11|     background: #fbf7ee; overflow: hidden;
12|     font-family: "Arial Narrow", Arial, sans-serif;
13|   }
14|   canvas {
15|     display: block;
16|     touch-action: none;
17|   }
18| </style>
19| </head>
20| <body>
21| <canvas id="game"></canvas>
22| <script>
23| // ---- Bridge helper (verbatim) ----
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| </script>
33| <script>
34| (function(){
35|   const canvas = document.getElementById("game");
36|   const ctx = canvas.getContext("2d");
37| 
38|   const PAPER = "#fbf7ee";
39|   const INK1 = "#ff48b0"; // pink
40|   const INK2 = "#0078bf"; // blue
41|   const OVERLAP = "#5b3a8c";
42| 
43|   let dpr = Math.max(1, window.devicePixelRatio || 1);
44|   let W = window.innerWidth, H = window.innerHeight;
45| 
46|   function resize() {
47|     W = window.innerWidth;
48|     H = window.innerHeight;
49|     dpr = Math.max(1, window.devicePixelRatio || 1);
50|     canvas.width = Math.floor(W * dpr);
51|     canvas.height = Math.floor(H * dpr);
52|     canvas.style.width = W + "px";
53|     canvas.style.height = H + "px";
54|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
55|     buildGrain();
56|   }
57|   window.addEventListener("resize", resize);
58| 
59|   // ---- grain tile (pre-rendered once, reused) ----
60|   let grainCanvas = null;
61|   function buildGrain() {
62|     const size = 128;
63|     grainCanvas = document.createElement("canvas");
64|     grainCanvas.width = size;
65|     grainCanvas.height = size;
66|     const gctx = grainCanvas.getContext("2d");
67|     const imgData = gctx.createImageData(size, size);
68|     for (let i = 0; i < imgData.data.length; i += 4) {
69|       const v = Math.random() * 255;
70|       imgData.data[i] = v;
71|       imgData.data[i+1] = v;
72|       imgData.data[i+2] = v;
73|       imgData.data[i+3] = 255;
74|     }
75|     gctx.putImageData(imgData, 0, 0);
76|   }
77| 
78|   function drawGrain() {
79|     if (!grainCanvas) return;
80|     ctx.save();
81|     ctx.globalAlpha = 0.08;
82|     ctx.globalCompositeOperation = "multiply";
83|     const pattern = ctx.createPattern(grainCanvas, "repeat");
84|     ctx.fillStyle = pattern;
85|     ctx.fillRect(0, 0, W, H);
86|     ctx.restore();
87|   }
88| 
89|   // ---- game state ----
90|   const LANES = 3;
91|   let laneX = [];
92|   let playerLane = 1;
93|   let playerDrawLane = 1; // for smooth transitions
94|   let running = false;
95|   let paused = false;
96|   let started = false;
97|   let score = 0;
98|   let scoreShown = 0;
99|   let speed = 260; // px/sec base scroll speed
100|   let elapsed = 0;
101|   let last = 0;
102|   let hazards = []; // {lane, y, type: 'comet'|'star'}
103|   let spawnTimer = 0;
104|   let spawnInterval = 1.4;
105|   let laneWidth = 0;
106|   let playerY = 0;
107|   let playerSize = 40;
108|   let bootSent = false;
109|   let hintPulse = 0;
110|   let bgOffset = 0;
111|   let firstHazardSpawned = false;
112|   let stageIndex = 1;
113|   let lastStageSpeed = speed;
114| 
115|   function computeLanes() {
116|     laneWidth = W / LANES;
117|     laneX = [];
118|     for (let i = 0; i < LANES; i++) {
119|       laneX.push(laneWidth * i + laneWidth / 2);
120|     }
121|     playerY = H - Math.max(H * 0.18, 90);
122|   }
123| 
124|   function resetState() {
125|     playerLane = 1;
126|     playerDrawLane = 1;
127|     running = false;
128|     paused = false;
129|     started = false;
130|     score = 0;
131|     scoreShown = 0;
132|     speed = 260;
133|     elapsed = 0;
134|     hazards = [];
135|     spawnTimer = 0;
136|     spawnInterval = 1.4;
137|     firstHazardSpawned = false;
138|     stageIndex = 1;
139|     lastStageSpeed = speed;
140|     computeLanes();
141|   }
142| 
143|   function backToTitle() {
144|     resetState();
145|   }
146| 
147|   resize();
148|   resetState();
149| 
150|   // ---- input ----
151|   canvas.style.touchAction = "none";
152|   canvas.addEventListener("pointerdown", (event) => {
153|     event.preventDefault();
154|     if (paused) return;
155|     if (!running) {
156|       running = true;
157|       started = true;
158|       CARTRIDGE.send("start");
159|       // spawn first hazard well ahead, keep opening lane clear
160|       spawnFirstHazard();
161|       return;
162|     }
163|     act(event);
164|   });
165| 
166|   function act(event) {
167|     // tap left half = move left, right half = move right
168|     const x = event.clientX;
169|     if (x < W / 2) {
170|       playerLane = Math.max(0, playerLane - 1);
171|     } else {
172|       playerLane = Math.min(LANES - 1, playerLane + 1);
173|     }
174|   }
175| 
176|   function spawnFirstHazard() {
177|     // spawn far away, and never in the player's current lane
178|     let lane = Math.floor(Math.random() * LANES);
179|     if (lane === playerLane) lane = (lane + 1) % LANES;
180|     hazards.push({ lane: lane, y: -H * 1.2, type: "comet" });
181|     firstHazardSpawned = true;
182|   }
183| 
184|   function spawnHazard() {
185|     const isStar = Math.random() < 0.35;
186|     const lane = Math.floor(Math.random() * LANES);
187|     hazards.push({ lane: lane, y: -60, type: isStar ? "star" : "comet" });
188|   }
189| 
190|   function addScore(v) {
191|     score += v;
192|     if (score < 0) score = 0;
193|     CARTRIDGE.send("score", { value: score });
194|   }
195| 
196|   function crash() {
197|     running = false;
198|     CARTRIDGE.send("end", { reason: "lose", value: score });
199|   }
200| 
201|   function advance(dt) {
202|     elapsed += dt;
203|     bgOffset += speed * dt;
204|     // ramp difficulty with speed over time (no levels)
205|     speed = 260 + Math.min(340, elapsed * 9);
206|     spawnInterval = Math.max(0.55, 1.4 - elapsed * 0.02);
207| 
208|     // send periodic "level" style stage markers via speed thresholds
209|     // (level event forbidden for arcade-run -> do not send)
210| 
211|     spawnTimer += dt;
212|     if (spawnTimer >= spawnInterval) {
213|       spawnTimer = 0;
214|       spawnHazard();
215|     }
216| 
217|     for (let h of hazards) {
218|       h.y += speed * dt;
219|     }
220|     hazards = hazards.filter(h => h.y < H + 80);
221| 
222|     // smooth player lane transition
223|     const targetX = laneX[playerLane];
224|     playerDrawLane += (playerLane - playerDrawLane) * Math.min(1, dt * 10);
225|   }
226| 
227|   function collide() {
228|     const px = laneX[playerLane];
229|     for (let h of hazards) {
230|       const dy = h.y - playerY;
231|       if (Math.abs(dy) < playerSize * 0.6 && h.lane === playerLane) {
232|         if (h.type === "star") {
233|           addScore(10);
234|           h.y = H + 1000; // remove
235|         } else {
236|           crash();
237|           return;
238|         }
239|       }
240|     }
241|   }
242| 
243|   // ---- drawing ----
244|   function drawBackground() {
245|     ctx.fillStyle = PAPER;
246|     ctx.fillRect(0, 0, W, H);
247| 
248|     // lane dividers, scrolling stripes for motion feedback
249|     ctx.save();
250|     ctx.strokeStyle = INK2;
251|     ctx.globalAlpha = 0.25;
252|     ctx.lineWidth = 3;
253|     for (let i = 1; i < LANES; i++) {
254|       const x = laneWidth * i;
255|       ctx.beginPath();
256|       const dashLen = 30, gap = 24;
257|       const offset = bgOffset % (dashLen + gap);
258|       for (let y = -dashLen + offset; y < H; y += dashLen + gap) {
259|         ctx.moveTo(x, y);
260|         ctx.lineTo(x, y + dashLen);
261|       }
262|       ctx.stroke();
263|     }
264|     ctx.restore();
265| 
266|     // drifting clouds (misregistered dots) for idle motion
267|     ctx.save();
268|     ctx.globalAlpha = 0.5;
269|     for (let i = 0; i < 6; i++) {
270|       const cx = (i * 137 + bgOffset * 0.2) % (W + 100) - 50;
271|       const cy = (i * 97) % H;
272|       ctx.fillStyle = INK1;
273|       ctx.beginPath();
274|       ctx.arc(cx, cy, 14, 0, Math.PI * 2);
275|       ctx.fill();
276|       ctx.fillStyle = INK2;
277|       ctx.beginPath();
278|       ctx.arc(cx + 2, cy + 2, 14, 0, Math.PI * 2);
279|       ctx.globalCompositeOperation = "multiply";
280|       ctx.fill();
281|       ctx.globalCompositeOperation = "source-over";
282|     }
283|     ctx.restore();
284|   }
285| 
286|   function drawComet(x, y) {
287|     ctx.save();
288|     ctx.translate(x, y);
289|     // tail (ink2)
290|     ctx.fillStyle = INK2;
291|     ctx.beginPath();
292|     ctx.moveTo(0, -8);
293|     ctx.lineTo(-14, -60);
294|     ctx.lineTo(14, -60);
295|     ctx.closePath();
296|     ctx.fill();
297|     // body (ink1, offset for misregistration)
298|     ctx.fillStyle = INK1;
299|     ctx.beginPath();
300|     ctx.arc(1, 1, 22, 0, Math.PI * 2);
301|     ctx.fill();
302|     // overlap core
303|     ctx.fillStyle = OVERLAP;
304|     ctx.beginPath();
305|     ctx.arc(0, 0, 10, 0, Math.PI * 2);
306|     ctx.fill();
307|     ctx.restore();
308|   }
309| 
310|   function drawStar(x, y) {
311|     ctx.save();
312|     ctx.translate(x, y);
313|     ctx.fillStyle = INK2;
314|     drawStarPath(2, 2, 18, 8);
315|     ctx.fill();
316|     ctx.fillStyle = INK1;
317|     drawStarPath(0, 0, 18, 8);
318|     ctx.fill();
319|     ctx.restore();
320|   }
321| 
322|   function drawStarPath(ox, oy, outerR, innerR) {
323|     ctx.beginPath();
324|     const spikes = 5;
325|     let rot = -Math.PI / 2;
326|     const step = Math.PI / spikes;
327|     ctx.moveTo(ox + Math.cos(rot) * outerR, oy + Math.sin(rot) * outerR);
328|     for (let i = 0; i < spikes; i++) {
329|       rot += step;
330|       ctx.lineTo(ox + Math.cos(rot) * innerR, oy + Math.sin(rot) * innerR);
331|       rot += step;
332|       ctx.lineTo(ox + Math.cos(rot) * outerR, oy + Math.sin(rot) * outerR);
333|     }
334|     ctx.closePath();
335|   }
336| 
337|   function drawPlayer() {
338|     const x = laneX[Math.round(playerDrawLane)] !== undefined
339|       ? (laneX[playerLane] * 0 + interpLaneX())
340|       : laneX[playerLane];
341|     const px = interpLaneX();
342|     ctx.save();
343|     ctx.translate(px, playerY);
344|     // ship shadow layer (ink2 offset)
345|     ctx.fillStyle = INK2;
346|     ctx.beginPath();
347|     ctx.moveTo(2, -26);
348|     ctx.lineTo(24, 22);
349|     ctx.lineTo(-20, 22);
350|     ctx.closePath();
351|     ctx.fill();
352|     // ship body ink1
353|     ctx.fillStyle = INK1;
354|     ctx.beginPath();
355|     ctx.moveTo(0, -28);
356|     ctx.lineTo(22, 20);
357|     ctx.lineTo(-22, 20);
358|     ctx.closePath();
359|     ctx.fill();
360|     // cockpit overlap
361|     ctx.fillStyle = OVERLAP;
362|     ctx.beginPath();
363|     ctx.arc(0, -2, 7, 0, Math.PI * 2);
364|     ctx.fill();
365|     ctx.restore();
366|   }
367| 
368|   function interpLaneX() {
369|     // linear interpolate between lane slots for smoothness
370|     return laneX[playerLane];
371|   }
372| 
373|   function drawHUD() {
374|     ctx.save();
375|     ctx.fillStyle = INK2;
376|     ctx.font = "bold 28px 'Arial Narrow', Arial, sans-serif";
377|     ctx.textBaseline = "top";
378|     ctx.fillText("SCORE " + Math.floor(scoreShown), 18, 16);
379|     ctx.restore();
380|   }
381| 
382|   function drawTitle() {
383|     ctx.save();
384|     ctx.fillStyle = OVERLAP;
385|     ctx.textAlign = "center";
386|     ctx.font = "bold 46px 'Arial Narrow', Arial, sans-serif";
387|     ctx.fillText("COMET LANE", W/2, H*0.28);
388|     ctx.fillText("RUNNER", W/2, H*0.28 + 52);
389| 
390|     const pulse = 0.5 + 0.5 * Math.sin(hintPulse);
391|     ctx.globalAlpha = 0.5 + pulse * 0.5;
392|     ctx.font = "bold 24px 'Arial Narrow', Arial, sans-serif";
393|     ctx.fillStyle = INK1;
394|     ctx.fillText("TAP TO BEGIN", W/2, H*0.55);
395|     ctx.globalAlpha = 1;
396|     ctx.font = "18px 'Arial Narrow', Arial, sans-serif";
397|     ctx.fillStyle = INK2;
398|     ctx.fillText("Tap left / right side to switch lanes", W/2, H*0.62);
399|     ctx.restore();
400|   }
401| 
402|   function drawEnd() {
403|     ctx.save();
404|     ctx.fillStyle = "rgba(251,247,238,0.85)";
405|     ctx.fillRect(0,0,W,H);
406|     ctx.fillStyle = OVERLAP;
407|     ctx.textAlign = "center";
408|     ctx.font = "bold 40px 'Arial Narrow', Arial, sans-serif";
409|     ctx.fillText("RUN OVER", W/2, H*0.32);
410|     ctx.font = "bold 30px 'Arial Narrow', Arial, sans-serif";
411|     ctx.fillStyle = INK1;
412|     ctx.fillText("SCORE " + Math.floor(score), W/2, H*0.42);
413| 
414|     const pulse = 0.5 + 0.5 * Math.sin(hintPulse);
415|     ctx.globalAlpha = 0.5 + pulse * 0.5;
416|     ctx.font = "22px 'Arial Narrow', Arial, sans-serif";
417|     ctx.fillStyle = INK2;
418|     ctx.fillText("TAP TO REPLAY", W/2, H*0.5);
419|     ctx.restore();
420|   }
421| 
422|   function draw() {
423|     drawBackground();
424| 
425|     if (started && running) {
426|       for (let h of hazards) {
427|         const x = laneX[h.lane];
428|         if (h.type === "comet") drawComet(x, h.y);
429|         else drawStar(x, h.y);
430|       }
431|       drawPlayer();
432|       drawHUD();
433|     } else if (!started) {
434|       // idle bobbing player preview + title
435|       drawPlayer();
436|       drawTitle();
437|     } else if (started && !running) {
438|       // after crash
439|       for (let h of hazards) {
440|         const x = laneX[h.lane];
441|         if (h.type === "comet") drawComet(x, h.y);
442|         else drawStar(x, h.y);
443|       }
444|       drawPlayer();
445|       drawHUD();
446|       drawEnd();
447|     }
448| 
449|     drawGrain();
450|   }
451| 
452|   // score smoothing toward actual score for nicer feedback
453|   function updateScoreShown(dt) {
454|     scoreShown += (score - scoreShown) * Math.min(1, dt * 8);
455|     if (Math.abs(score - scoreShown) < 0.1) scoreShown = score;
456|   }
457| 
458|   // handle tap-to-replay after end
459|   let wantReplayListener = false;
460|   canvas.addEventListener("pointerdown", (event) => {
461|     if (started && !running && !paused) {
462|       // replay
463|       event.preventDefault();
464|       resetState();
465|     }
466|   });
467| 
468|   function frame(now) {
469|     const dt = Math.min((now - last) / 1000, 0.05);
470|     last = now;
471|     hintPulse += dt * 3;
472|     if (running && !paused) {
473|       advance(dt);
474|       collide();
475|     }
476|     updateScoreShown(dt);
477|     draw();
478|     if (!bootSent) {
479|       CARTRIDGE.send("boot", { title: "Comet Lane Runner", gameType: "arcade-run", lang: "en" });
480|       bootSent = true;
481|     }
482|     requestAnimationFrame(frame);
483|   }
484|   requestAnimationFrame(frame);
485| 
486|   // ---- host commands ----
487|   window.addEventListener("message", (event) => {
488|     const data = event.data;
489|     if (!data || data.source !== "cartridge-host") return;
490|     if (data.type === "pause") paused = true;
491|     if (data.type === "resume") paused = false;
492|     if (data.type === "reset") backToTitle();
493|   });
494| 
495| })();
496| </script>
497| </body>
498| </html>
499|

